WITH filtered AS (SELECT *, ROUND(units * 100, 2) AS adjusted_units, DATE_ADD(sale_date, 9) AS sale_date_plus_9d FROM store_sales WHERE sale_date > DATE '2023-08-21') SELECT store_id, product_id, COUNT(*) AS num_rows, STDDEV_SAMP(revenue) AS revenue_stddev, CORR(units, revenue) AS corr_units_revenue FROM filtered GROUP BY store_id, product_id HAVING COUNT(*) >= 1 ORDER BY store_id DESC NULLS LAST;
